mobile/replay-gpx.mjs.text:
#!/usr/bin/env node
// Replay recorded GPX files through the drive detector and print what it found.
//   node replay-gpx.mjs day1.gpx [day2.gpx ...] [--stopDwellMs=300000] [--startSpeed=4.5] ...
// Any DEFAULTS key can be overridden as --key=value, so thresholds can be
// compared on the same recording. Reads local files only; nothing is sent.
import { readFileSync } from "node:fs";
import { parseGpx } from "./src/gpx.mjs";
import { detectTrips, DEFAULTS } from "./src/tripdetect.mjs";

const files = [], options = {};
for (const a of process.argv.slice(2)) {
  const m = a.match(/^--(\w+)=(.+)$/);
  if (!m) { files.push(a); continue; }
  if (!(m[1] in DEFAULTS) || !Number.isFinite(Number(m[2]))) { console.error(`unknown option ${a}; keys: ${Object.keys(DEFAULTS).join(", ")}`); process.exit(2); }
  options[m[1]] = Number(m[2]);
}
if (!files.length) { console.error("usage: node replay-gpx.mjs file.gpx [...] [--key=value]"); process.exit(2); }

let total = 0;
for (const f of files) {
  const fixes = parseGpx(readFileSync(f, "utf8"));
  const trips = detectTrips(fixes, options);
  console.log(`${f}: ${fixes.length} fixes, ${trips.length} drive(s)`);
  for (const t of trips) {
    const mins = Math.round((t.endedAt - t.startedAt) / 60e3);
    console.log(`  ${new Date(t.startedAt).toISOString()}  ${t.miles.toFixed(1)} mi  ${mins} min`);
    total += t.miles;
  }
}
console.log(`total ${total.toFixed(2)} mi (options: ${JSON.stringify(options)})`);

mobile/src/background.js.text:
// Background location task. The OS wakes this with batches of fixes even when
// the app is closed; each batch runs through the pure detector, and finished
// drives land in the pending list for the user to classify.
import * as TaskManager from "expo-task-manager";
import * as Location from "expo-location";
import { initial, step, settle } from "./tripdetect.mjs";
import { loadEngine, saveEngine, addPending } from "./store";

export const TASK = "mileage-log-background";

TaskManager.defineTask(TASK, async ({ data, error }) => {
  if (error || !data) return;
  let state = await loadEngine(initial());
  for (const l of data.locations) {
    const r = step(state, {
      lat: l.coords.latitude, lon: l.coords.longitude, t: l.timestamp,
      speed: l.coords.speed, accuracy: l.coords.accuracy,
    });
    state = r.state;
    if (r.trip) await addPending(r.trip);
  }
  await saveEngine(state);
});

// Called when the app opens: a drive the OS stopped reporting on is closed now.
export async function settleDrives(now = Date.now()) {
  const r = settle(await loadEngine(initial()), now);
  if (r.trip) await addPending(r.trip);
  if (r.trip || r.state.mode === "idle") await saveEngine(r.state);
  return r.trip;
}

export async function startTracking() {
  const fg = await Location.requestForegroundPermissionsAsync();
  if (fg.status !== "granted") return "foreground-denied";
  const bg = await Location.requestBackgroundPermissionsAsync();
  if (bg.status !== "granted") return "background-denied";
  if (await Location.hasStartedLocationUpdatesAsync(TASK)) return "running";
  await Location.startLocationUpdatesAsync(TASK, {
    accuracy: Location.Accuracy.Balanced,
    distanceInterval: 50,       // metres; saves battery when parked
    deferredUpdatesInterval: 15000,
    pausesUpdatesAutomatically: true,
    activityType: Location.ActivityType.AutomotiveNavigation,
    showsBackgroundLocationIndicator: true,
    foregroundService: {
      notificationTitle: "Mileage Log is recording drives",
      notificationBody: "Locations stay on this phone.",
    },
  });
  return "started";
}

export const stopTracking = async () => {
  if (await Location.hasStartedLocationUpdatesAsync(TASK)) await Location.stopLocationUpdatesAsync(TASK);
};

mobile/src/classify.mjs.text:
// Suggests a category for a detected drive from how the user classified earlier
// drives, so the daily review is a one-swipe confirmation. A small, explainable
// model (place votes with a time-of-week prior), not a black box: it can say why.
// Pure functions. Nothing leaves the device.

import { haversineMiles } from "../../calc.mjs";

export const CATEGORIES = ["business", "medical", "charity", "commute", "personal"];
const NEAR_MILES = 0.1; // ~160 m: same place

// history: [{ to: {lat, lon}, from?: {lat, lon}, category, startedAt }]
// trip:    { to, from?, startedAt }
export function suggestCategory(history, trip, { utcOffsetMin = 0, minVotes = 2 } = {}) {
  const votes = Object.fromEntries(CATEGORIES.map((c) => [c, 0]));
  let matches = 0;
  for (const h of history) {
    if (!CATEGORIES.includes(h.category)) continue;
    const dest = haversineMiles(h.to, trip.to);
    if (dest > NEAR_MILES) continue;
    let w = 1;
    // Same origin as well as destination is a stronger match (a route, not a place).
    if (h.from && trip.from && haversineMiles(h.from, trip.from) <= NEAR_MILES) w += 1;
    // Same weekday-type and time-of-day band: an 8am weekday drive to the office is a commute.
    if (sameSlot(h.startedAt, trip.startedAt, utcOffsetMin)) w += 0.5;
    votes[h.category] += w;
    matches++;
  }
  if (matches < minVotes) return null;
  const total = Object.values(votes).reduce((a, b) => a + b, 0);
  const [category, top] = Object.entries(votes).sort((a, b) => b[1] - a[1])[0];
  const confidence = Math.round((top / total) * 100) / 100;
  return {
    category,
    confidence,
    reason: `${matches} earlier drive${matches === 1 ? "" : "s"} to this place; ${Math.round(confidence * 100)}% were ${category}.`,
    auto: confidence >= 0.9 && matches >= 3, // safe to pre-select; still shown for review
  };
}

function slot(t, off) {
  const d = new Date(t + off * 60e3);
  const dow = d.getUTCDay();
  return { weekend: dow === 0 || dow === 6, band: Math.floor(d.getUTCHours() / 3) };
}
function sameSlot(a, b, off) {
  const x = slot(a, off), y = slot(b, off);
  return x.weekend === y.weekend && x.band === y.band;
}

// Converts a detected drive plus the user's category into a trip record in the
// web app's format (calc.mjs normalizeTrip), so exports and the audit check are shared.
export function toLogTrip(drive, category, { utcOffsetMin = 0, purpose = "", to = "", from = "", client = "" } = {}) {
  const date = new Date(drive.startedAt + utcOffsetMin * 60e3).toISOString().slice(0, 10);
  return {
    date, category, from, to, purpose, client,
    odoStart: "", odoEnd: "", miles: drive.miles, tolls: 0, parking: 0,
    enteredAt: new Date(drive.endedAt).toISOString(), // logged at the drive, which the audit check rewards
    gps: true,
  };
}

mobile/src/gpx.mjs.text:
// Reads a recorded GPS track (GPX 1.0/1.1) into the fix format tripdetect.mjs
// takes, so the detector's thresholds can be tuned on real drives instead of
// simulated ones. No XML library: GPX trackpoints are flat enough for a scan.
//
// A fix is { lat, lon, t (ms), speed (m/s or null), accuracy (m or null) }.
// Points with no time are skipped (nothing to replay). <speed> (m/s) is read
// from the point or its <extensions>; <hdop> x 5 m stands in for accuracy.

const attr = (s, name) => { const m = s.match(new RegExp(`\\b${name}\\s*=\\s*["']([^"']+)["']`)); return m ? Number(m[1]) : NaN; };
const tag = (s, name) => { const m = s.match(new RegExp(`<(?:\\w+:)?${name}>\\s*([^<]*?)\\s*</(?:\\w+:)?${name}>`)); return m ? m[1] : null; };

export function parseGpx(xml) {
  const fixes = [];
  const re = /<trkpt\b([^>]*?)(?:\/>|>([\s\S]*?)<\/trkpt>)/g;
  let m;
  while ((m = re.exec(String(xml)))) {
    const lat = attr(m[1], "lat"), lon = attr(m[1], "lon");
    const time = tag(m[2] || "", "time");
    const t = time ? Date.parse(time) : NaN;
    if (!Number.isFinite(lat) || !Number.isFinite(lon) || !Number.isFinite(t)) continue;
    if (Math.abs(lat) > 90 || Math.abs(lon) > 180) continue;
    const sp = tag(m[2] || "", "speed"), hd = tag(m[2] || "", "hdop");
    const speed = sp != null && Number.isFinite(Number(sp)) && Number(sp) >= 0 ? Number(sp) : null;
    const accuracy = hd != null && Number.isFinite(Number(hd)) ? Number(hd) * 5 : null;
    fixes.push({ lat, lon, t, speed, accuracy });
  }
  return fixes.sort((a, b) => a.t - b.t);
}

mobile/src/places.mjs.text:
// Named places: the fix for a log that says "40.01,-75.02 -> 40.05,-75.10".
// Name a place once ("Home", "Smith job site") and every later drive to or from
// it is labelled, and a business destination remembers its usual purpose and
// client, so the daily review becomes a confirmation instead of typing.
// Pure functions over plain data. Nothing leaves the device, and no reverse
// geocoding service is called (that would send coordinates to a third party).

import { haversineMiles } from "../../calc.mjs";
import { toLogTrip } from "./classify.mjs";

export const PLACE_RADIUS_MILES = 0.1; // ~160 m: same place as classify.mjs

// places: [{ id, name, lat, lon, purpose?, client?, category? }]
export function placeAt(places, point, radius = PLACE_RADIUS_MILES) {
  if (!point) return null;
  let best = null, bestD = Infinity;
  for (const p of places) {
    const d = haversineMiles(p, point);
    if (d <= radius && d < bestD) { best = p; bestD = d; }
  }
  return best;
}

// Adds a place, or renames the existing one when the point is already named.
export function addPlace(places, { name, lat, lon }) {
  const label = String(name || "").trim();
  if (!label) return places;
  const hit = placeAt(places, { lat, lon });
  if (hit) return places.map((p) => (p.id === hit.id ? { ...p, name: label } : p));
  return [...places, { id: "p" + Math.round(lat * 1e5) + "_" + Math.round(lon * 1e5), name: label, lat, lon }];
}

export function removePlace(places, id) {
  return places.filter((p) => p.id !== id);
}

// What the review card shows for a detected drive.
// drive: { from: {lat, lon}, to: {lat, lon}, ... }
export function describeDrive(places, drive) {
  const a = placeAt(places, drive.from), b = placeAt(places, drive.to);
  return {
    from: a ? a.name : "", to: b ? b.name : "",
    fromPlace: a, toPlace: b,
    // Unnamed ends the user may want to name; a trip with no destination name
    // is one of the gaps the audit check flags.
    unnamed: [!a && "from", !b && "to"].filter(Boolean),
    purpose: b?.purpose || "", client: b?.client || "",
  };
}

// Builds the log record for a classified drive, labelled with place names.
export function logTripFor(places, drive, category, { utcOffsetMin = 0, purpose = "", client = "" } = {}) {
  const d = describeDrive(places, drive);
  return toLogTrip(drive, category, {
    utcOffsetMin, from: d.from, to: d.to,
    purpose: purpose.trim() || d.purpose, client: client.trim() || d.client,
  });
}

// After a business drive is classified, its destination remembers the purpose
// and client, so the next drive there needs no typing. Other categories leave
// the memory alone (a drive to the office on a weekend is not a new purpose).
export function remember(places, drive, category, { purpose = "", client = "" } = {}) {
  const b = placeAt(places, drive.to);
  if (!b || category !== "business" || !purpose.trim()) return places;
  return places.map((p) => (p.id === b.id ? { ...p, purpose: purpose.trim(), client: client.trim() || p.client || "" } : p));
}

// Drives the user can confirm in one tap: the category model is sure (auto)
// and, for business, a purpose is known. Returns [{ drive, category, purpose, client }].
export function readyToConfirm(pending, suggestFor, places) {
  const out = [];
  for (const drive of pending) {
    const s = suggestFor(drive);
    if (!s || !s.auto) continue;
    const d = describeDrive(places, drive);
    if (!d.to) continue; // an unnamed destination still needs the user
    if (s.category === "business" && !d.purpose) continue;
    out.push({ drive, category: s.category, purpose: d.purpose, client: d.client });
  }
  return out;
}

mobile/src/schedule.mjs.text:
// Work-hours rule: the cold-start answer for drives the history model has never
// seen. "Weekdays 8-18 are usually business" is how MileIQ-style apps get a new
// user to a one-tap review on day one. It is only ever a *suggestion*: it never
// sets `auto`, so "Confirm N drives I recognise" does not file it, and a
// business trip still needs the user's purpose and a named destination.
// Pure functions. Nothing leaves the device.

export const DEFAULT_SCHEDULE = { enabled: false, days: [1, 2, 3, 4, 5], startHour: 8, endHour: 18, category: "business" };

export function normalizeSchedule(s = {}) {
  const d = DEFAULT_SCHEDULE;
  const days = Array.isArray(s.days) ? [...new Set(s.days.map(Number).filter((x) => Number.isInteger(x) && x >= 0 && x <= 6))].sort() : d.days;
  const hour = (v, fb) => (v !== "" && v !== null && v !== undefined && Number.isInteger(Number(v)) && Number(v) >= 0 && Number(v) <= 24 ? Number(v) : fb);
  let startHour = hour(s.startHour, d.startHour), endHour = hour(s.endHour, d.endHour);
  if (endHour <= startHour) { startHour = d.startHour; endHour = d.endHour; }
  const category = ["business", "medical", "charity", "commute", "personal"].includes(s.category) ? s.category : d.category;
  return { enabled: s.enabled === true, days, startHour, endHour, category };
}

export function toggleDay(schedule, day) {
  const s = normalizeSchedule(schedule);
  const days = s.days.includes(day) ? s.days.filter((x) => x !== day) : [...s.days, day].sort();
  return { ...s, days };
}

// trip: { startedAt }. Returns the same shape as classify.suggestCategory, or null.
export function scheduleSuggestion(schedule, trip, { utcOffsetMin = 0 } = {}) {
  const s = normalizeSchedule(schedule);
  if (!s.enabled || s.days.length === 0 || !trip) return null;
  const local = new Date(trip.startedAt + utcOffsetMin * 60e3);
  const hour = local.getUTCHours() + local.getUTCMinutes() / 60;
  if (!s.days.includes(local.getUTCDay()) || hour < s.startHour || hour >= s.endHour) return null;
  return {
    category: s.category,
    confidence: 0.5,
    reason: `inside your work hours (${s.startHour}:00-${s.endHour}:00); a guess, not a pattern from your history.`,
    auto: false,
    source: "schedule",
  };
}

// History first (it knows the place); the schedule only fills the gap.
export function suggestWithSchedule(historySuggestion, schedule, trip, opts) {
  return historySuggestion || scheduleSuggestion(schedule, trip, opts);
}

mobile/src/store.js.text:
// On-device storage only. Nothing here is sent anywhere.
import AsyncStorage from "@react-native-async-storage/async-storage";

const K = { engine: "ml.engine", pending: "ml.pending", trips: "ml.trips", places: "ml.places", vehicles: "ml.vehicles", active: "ml.activeVehicle", schedule: "ml.schedule" };
const read = async (k, d) => { try { const v = await AsyncStorage.getItem(k); return v ? JSON.parse(v) : d; } catch { return d; } };
const write = (k, v) => AsyncStorage.setItem(k, JSON.stringify(v));

export const loadEngine = (initial) => read(K.engine, initial);
export const saveEngine = (s) => write(K.engine, s);
export const loadPending = () => read(K.pending, []);
export const loadTrips = () => read(K.trips, []);
export const loadPlaces = () => read(K.places, []);
export const savePlaces = (p) => write(K.places, p);
export const loadVehicles = () => read(K.vehicles, []);
export const saveVehicles = (v) => write(K.vehicles, v);
export const loadActiveVehicle = () => read(K.active, "");
export const saveActiveVehicle = (v) => write(K.active, v);
export const loadSchedule = () => read(K.schedule, null);
export const saveSchedule = (s) => write(K.schedule, s);
export const saveTrips = (t) => write(K.trips, t);
export async function deleteTrip(id) {
  await write(K.trips, (await loadTrips()).filter((t) => t.id !== id));
}

export async function addPending(drive) {
  const list = await loadPending();
  list.push({ id: String(drive.startedAt), ...drive });
  await write(K.pending, list);
}

// Classify a pending drive: moves it into the log in the web app's trip format.
export async function classify(id, logTrip, drive) {
  const pending = (await loadPending()).filter((p) => p.id !== id);
  const trips = await loadTrips();
  trips.push({ ...logTrip, id: "m" + id, to_loc: drive.to, from_loc: drive.from, startedAt: drive.startedAt });
  await write(K.pending, pending);
  await write(K.trips, trips);
}
export async function dismiss(id) {
  await write(K.pending, (await loadPending()).filter((p) => p.id !== id));
}

mobile/src/tripdetect.mjs.text:
// Automatic drive detection from a stream of GPS fixes: the part of a mileage
// tracker a web page cannot do (it needs a background location task). Pure
// functions, no platform imports, so the same code runs in the phone app and
// under `node --test`.
//
// A fix is { lat, lon, t (ms since epoch), speed (m/s or null), accuracy (m) }.
// step(state, fix) returns { state, trip }, where trip is non-null when a drive
// has just ended. flush(state) ends a drive that is still open (app shutdown).

import { haversineMiles } from "../../calc.mjs";

export const DEFAULTS = {
  maxAccuracy: 50,       // metres; worse fixes are ignored
  startSpeed: 4.5,       // m/s (~10 mph) counts as driving, not walking or cycling
  startFixes: 2,         // consecutive driving fixes needed to open a trip
  stopSpeed: 1.2,        // m/s below this counts as stopped
  stopDwellMs: 5 * 60e3, // stopped this long ends the trip (traffic lights do not)
  maxJumpSpeed: 70,      // m/s (~157 mph): an implied speed above this is a GPS glitch
  minStep: 0.01,         // miles; ignore jitter smaller than ~16 m while moving
  minMiles: 0.2,         // shorter drives are dropped (moving the car, parking lots)
  minDurationMs: 60e3,
  runGapMs: 2 * 60e3,    // moving fixes this far apart are not one run (OS paused updates between them)
};

export const initial = () => ({ mode: "idle", last: null, run: [], runOrigin: null, trip: null, stoppedSince: null });

const M_PER_MILE = 1609.344;

// Speed in m/s: the device value when present, else derived from the previous fix.
function speedOf(prev, fix) {
  if (fix.speed != null && fix.speed >= 0) return fix.speed;
  if (!prev) return 0;
  const dt = (fix.t - prev.t) / 1000;
  if (dt <= 0) return 0;
  return (haversineMiles(prev, fix) * M_PER_MILE) / dt;
}

export function step(state, fix, options = {}) {
  const o = { ...DEFAULTS, ...options };
  if (fix.accuracy != null && fix.accuracy > o.maxAccuracy) return { state, trip: null };
  if (state.last && fix.t <= state.last.t) return { state, trip: null };

  // Phones stop delivering fixes once parked (pausesUpdatesAutomatically), so a
  // drive can stay open for hours. A silence as long as the dwell time means the
  // car stopped: close that drive where it last moved, then treat this fix as
  // the first of a new one. Without this, two drives hours apart merge into one.
  if (state.mode === "driving" && state.last && fix.t - state.last.t >= o.stopDwellMs) {
    const closed = finish(state.trip, o);
    const r = step(initial(), fix, options); // no stale origin: its time and place are hours old
    return { state: r.state, trip: closed || r.trip };
  }
  if (state.mode === "idle" && state.run.length && state.last && fix.t - state.last.t > o.runGapMs) {
    return step(initial(), fix, options);
  }

  // Reject teleports: the implied speed between two fixes cannot be a car.
  if (state.last) {
    const dt = (fix.t - state.last.t) / 1000;
    const implied = (haversineMiles(state.last, fix) * M_PER_MILE) / dt;
    if (implied > o.maxJumpSpeed) return { state, trip: null };
  }

  const v = speedOf(state.last, fix);
  const moving = v >= o.startSpeed;
  const stopped = v < o.stopSpeed;
  const prev = state.last;
  const next = { ...state, last: fix };

  if (state.mode === "idle") {
    if (!moving) return { state: { ...next, run: [], runOrigin: null }, trip: null };
    // The trip began at the fix before the run, where the car was still parked.
    const runOrigin = state.run.length ? state.runOrigin : prev;
    const run = [...state.run, fix];
    if (run.length < o.startFixes) return { state: { ...next, run, runOrigin }, trip: null };
    const first = runOrigin || run[0];
    const trip = { startFix: first, endFix: fix, lastMoving: fix, miles: 0, fixes: 1, lastCounted: first };
    let t = trip;
    for (const f of run) t = advance(t, f, o);
    return { state: { ...next, mode: "driving", run: [], runOrigin: null, trip: t, stoppedSince: null }, trip: null };
  }

  // driving
  let t = state.trip;
  let stoppedSince = state.stoppedSince;
  if (stopped) {
    if (stoppedSince == null) stoppedSince = fix.t;
    if (fix.t - stoppedSince >= o.stopDwellMs) {
      return { state: { ...initial(), last: fix }, trip: finish(t, o) };
    }
    return { state: { ...next, trip: t, stoppedSince }, trip: null };
  }
  stoppedSince = null;
  t = advance(t, fix, o);
  return { state: { ...next, trip: t, stoppedSince }, trip: null };
}

function advance(t, fix, o) {
  const d = haversineMiles(t.lastCounted, fix);
  if (d < o.minStep) return { ...t, endFix: fix, lastMoving: fix };
  return { ...t, miles: t.miles + d, fixes: t.fixes + 1, lastCounted: fix, endFix: fix, lastMoving: fix };
}

function finish(t, o) {
  // The drive ended when the car last moved, not when the dwell timer fired.
  const endedAt = t.lastMoving.t;
  const startedAt = t.startFix.t;
  const miles = Math.round(t.miles * 10) / 10;
  if (t.miles < o.minMiles || endedAt - startedAt < o.minDurationMs) return null;
  return {
    startedAt,
    endedAt,
    miles,
    from: { lat: t.startFix.lat, lon: t.startFix.lon },
    to: { lat: t.lastMoving.lat, lon: t.lastMoving.lon },
  };
}

// Close a drive the OS stopped reporting on. Call it with the current time when
// the app comes to the foreground: if nothing has moved for the dwell time, the
// drive is over and is returned like any other.
export function settle(state, now, options = {}) {
  const o = { ...DEFAULTS, ...options };
  if (state.mode !== "driving" || now - state.trip.lastMoving.t < o.stopDwellMs) return { state, trip: null };
  return { state: { ...initial(), last: state.last }, trip: finish(state.trip, o) };
}

export function flush(state, options = {}) {
  const o = { ...DEFAULTS, ...options };
  if (state.mode !== "driving") return { state: initial(), trip: null };
  return { state: initial(), trip: finish(state.trip, o) };
}

// Runs a whole recorded track; handy for tests and for replaying a saved day.
export function detectTrips(fixes, options = {}) {
  let state = initial();
  const trips = [];
  for (const f of fixes) {
    const r = step(state, f, options);
    state = r.state;
    if (r.trip) trips.push(r.trip);
  }
  const end = flush(state, options);
  if (end.trip) trips.push(end.trip);
  return trips;
}

mobile/src/vehicles.mjs.text:
// Vehicles and backup, as pure functions (no platform imports).
//
// The standard mileage rate is claimed per vehicle and Schedule C Part IV asks
// for miles per vehicle, so every drive carries the vehicle it was made in.
// Trips live only on the phone, so a lost phone would lose the log the audit
// check relies on: the backup is the web app's own JSON export (calc.mjs
// exportJson) with the phone-only parts (places, vehicles) in `settings`.

import { exportJson, importJson, vehicleNames } from "../../calc.mjs";

export const cleanName = (s) => String(s || "").trim().replace(/\s+/g, " ").slice(0, 40);

// Adds a vehicle name to the list (case-insensitive de-dupe, keeps the first spelling).
export function addVehicle(list, name) {
  const n = cleanName(name);
  if (!n || list.some((v) => v.toLowerCase() === n.toLowerCase())) return list;
  return [...list, n];
}

// Vehicles known from the saved list plus any already on logged trips.
export function knownVehicles(saved, trips) {
  return vehicleNames(trips).reduce(addVehicle, saved.reduce(addVehicle, []));
}

// Stamps the chosen vehicle onto a log record built by places.logTripFor.
export const withVehicle = (log, vehicle) => ({ ...log, vehicle: cleanName(vehicle) });

// Backup text: web-app-compatible JSON plus the phone's places and vehicles.
export function makeBackup({ trips, places = [], vehicles = [], activeVehicle = "" }, now = new Date()) {
  const text = exportJson(trips, { places, vehicles, activeVehicle, source: "mileage-log-mobile" });
  return text.replace(/"exportedAt": "[^"]*"/, `"exportedAt": "${now.toISOString()}"`);
}

// Merges a backup (or a web-app export) into what is on the phone. Never drops
// anything already there: trips merge by id, places by id, vehicles by name.
export function restoreBackup(text, { trips, places = [], vehicles = [] }) {
  const r = importJson(text, trips);
  if (r.error) return { error: r.error, trips, places, vehicles, added: 0 };
  const s = r.settings || {};
  const have = new Set(places.map((p) => p.id));
  const mergedPlaces = [...places, ...(Array.isArray(s.places) ? s.places : []).filter((p) => p && p.id && !have.has(p.id) && Number.isFinite(p.lat) && Number.isFinite(p.lon))];
  const mergedVehicles = knownVehicles(
    (Array.isArray(s.vehicles) ? s.vehicles : []).reduce(addVehicle, vehicles),
    r.trips,
  );
  return { error: null, trips: r.trips, places: mergedPlaces, vehicles: mergedVehicles, added: r.added };
}

reimburse.mjs.text:
// Employer mileage-reimbursement claim. Since 2018 an employee cannot deduct
// unreimbursed business mileage on a federal return, so the useful document is
// a claim to the employer under an accountable plan: date, destination,
// business purpose and miles for every trip, priced at the employer's own
// per-mile rate (any rate; the IRS rate is only the tax-free ceiling).
// Pure functions, no DOM, no network. Not tax or legal advice.
import { tripMiles, rateFor, money } from "./calc.mjs";

const h = (s) => String(s ?? "").replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
const cents = (dollars) => Math.round(dollars * 100 + 1e-9);
const round1 = (n) => Math.round(n * 10) / 10;

// Business trips in [from, to] (inclusive ISO dates; either may be empty),
// each priced in whole cents so the rows always add up to the total.
// `rate` is the employer's $/mile; null/blank uses the IRS business rate on
// each trip's date, and `usedIrsRate` says so. Zero-mile trips are skipped.
export function reimbursementClaim(trips, { from = "", to = "", rate = null, override = {}, client = "" } = {}) {
  const custom = rate !== null && rate !== "" && Number.isFinite(Number(rate)) && Number(rate) >= 0 ? Number(rate) : null;
  const rows = [];
  for (const t of trips) {
    if (t.category !== "business") continue;
    if (from && t.date < from) continue;
    if (to && t.date > to) continue;
    if (client && (t.client || "") !== client) continue;
    const miles = tripMiles(t);
    if (!(miles > 0)) continue;
    const r = custom ?? rateFor(t.date, "business", override) ?? 0;
    rows.push({ ...t, miles, rate: r, cents: cents(miles * r), missing: !String(t.to || "").trim() || !String(t.purpose || "").trim() });
  }
  rows.sort((a, b) => a.date.localeCompare(b.date));
  const byMonth = new Map();
  for (const r of rows) {
    const m = r.date.slice(0, 7), g = byMonth.get(m) || { month: m, miles: 0, cents: 0, trips: 0 };
    g.miles = round1(g.miles + r.miles); g.cents += r.cents; g.trips += 1; byMonth.set(m, g);
  }
  return {
    rows,
    months: [...byMonth.values()].sort((a, b) => a.month.localeCompare(b.month)),
    miles: round1(rows.reduce((s, r) => s + r.miles, 0)),
    cents: rows.reduce((s, r) => s + r.cents, 0),
    usedIrsRate: custom === null,
    incomplete: rows.filter((r) => r.missing).length,
    // Reimbursing above the IRS rate is allowed but the excess is taxable wages.
    overIrsCents: custom === null ? 0 : rows.reduce((s, r) => s + Math.max(0, r.cents - cents(r.miles * (rateFor(r.date, "business", override) ?? 0))), 0),
  };
}

export function reimbursementHtml(trips, { name = "", employer = "", generated = new Date().toISOString().slice(0, 10), ...opts } = {}) {
  const c = reimbursementClaim(trips, opts);
  const d = (x) => money(x / 100);
  const rows = c.rows.map((r) => `<tr><td>${h(r.date)}</td><td>${h(r.from)}${r.from && r.to ? " &rarr; " : ""}${h(r.to)}</td><td>${h(r.purpose)}${r.client ? " (" + h(r.client) + ")" : ""}</td><td>${h(r.vehicle)}</td><td class="n">${r.miles}</td><td class="n">$${r.rate.toFixed(3)}</td><td class="n">${d(r.cents)}</td></tr>`).join("");
  const months = c.months.map((m) => `<tr><td>${h(m.month)}</td><td class="n">${m.trips}</td><td class="n">${m.miles}</td><td class="n">${d(m.cents)}</td></tr>`).join("");
  const period = opts.from || opts.to ? `${h(opts.from || "start")} to ${h(opts.to || "latest")}` : "all dates in the log";
  return `<!doctype html><html lang="en"><head><meta charset="utf-8"><title>Mileage reimbursement claim</title>
<style>body{font:13px/1.45 system-ui,sans-serif;margin:28px;color:#111}h1{font-size:20px;margin:0 0 4px}h2{font-size:15px;margin:22px 0 6px}table{border-collapse:collapse;width:100%}th,td{border:1px solid #bbb;padding:4px 6px;text-align:left;vertical-align:top}th{background:#eee}td.n,th.n{text-align:right}.note{color:#444;font-size:12px}.sig{margin-top:30px}@media print{body{margin:10mm}tr{break-inside:avoid}}</style></head><body>
<h1>Mileage reimbursement claim</h1>
<p>${name ? "Employee: <strong>" + h(name) + "</strong>. " : ""}${employer ? "Employer: <strong>" + h(employer) + "</strong>. " : ""}Period: ${period}. Prepared ${h(generated)}.</p>
<table><tbody><tr><th>Business trips</th><td class="n">${c.rows.length}</td><th>Business miles</th><td class="n">${c.miles}</td></tr>
<tr><th>Rate</th><td class="n">${c.usedIrsRate ? "IRS business rate on each trip's date" : "$" + Number(opts.rate).toFixed(3) + " per mile (employer rate)"}</td><th>Amount claimed</th><td class="n"><strong>${d(c.cents)}</strong></td></tr></tbody></table>
${c.incomplete ? `<p class="note"><strong>${c.incomplete} trip(s) lack a destination or purpose.</strong> An accountable plan normally requires both; add them before submitting.</p>` : ""}
<h2>By month</h2><table><thead><tr><th>Month</th><th class="n">Trips</th><th class="n">Miles</th><th class="n">Amount</th></tr></thead><tbody>${months}</tbody></table>
<h2>Trips</h2><table><thead><tr><th>Date</th><th>Route</th><th>Business purpose</th><th>Vehicle</th><th class="n">Miles</th><th class="n">Rate</th><th class="n">Amount</th></tr></thead><tbody>${rows}</tbody></table>
<p class="sig">Employee signature: ______________________ Date: ____________</p>
<p class="note">A record of trips the employee entered, priced at the stated rate. Reimbursements under an accountable plan up to the IRS rate are generally not taxable wages; amounts above it generally are. Your employer's policy decides what is reimbursable. Not tax or legal advice.</p>
</body></html>`;
}

usage.mjs.text:
const KEY = "mileage-log-usage";
// Separate from the counters on purpose: opting out *removes* the
// counters, so a flag stored inside them would be deleted by the very
// act it records.
const OPT_OUT = "mileage-log-usage-opt-out";

// The in-memory flag is only a same-page fast path. `globalThis` is a
// fresh realm on every page load, so without the stored key the switch
// silently stops working on the visitor's next visit -- and they do not
// look again, because they believe they already used it.
function usageOptedOut() {
  if (globalThis.__usageOptOut) return true;
  try {
    return typeof localStorage !== "undefined" && localStorage.getItem(OPT_OUT) === "1";
  } catch {
    // A blocked or full store must never be read as consent.
    return false;
  }
}

function usageBlocked() {
  if (usageOptedOut()) return true;
  try {
    if (navigator.doNotTrack === "1" || navigator.globalPrivacyControl) return true;
  } catch {
    /* navigator is optional in tests */
  }
  return false;
}

export function record(event) {
  if (typeof localStorage === "undefined" || usageBlocked()) return;
  let current;
  try {
    current = JSON.parse(localStorage.getItem(KEY) || "{}");
  } catch {
    current = {};
  }
  if (!current || typeof current !== "object" || Array.isArray(current)) current = {};
  current[event] = (current[event] || 0) + 1;
  try {
    localStorage.setItem(KEY, JSON.stringify(current));
  } catch {
    /* storage is optional */
  }
}

export function readUsage() {
  if (typeof localStorage === "undefined") return {};
  try {
    const parsed = JSON.parse(localStorage.getItem(KEY) || "{}");
    return parsed && typeof parsed === "object" && !Array.isArray(parsed) ? parsed : {};
  } catch {
    return {};
  }
}

export function setUsageOptOut(value) {
  const off = Boolean(value);
  globalThis.__usageOptOut = off;
  if (typeof localStorage === "undefined") return;
  if (off) {
    try { localStorage.removeItem(KEY); } catch { /* storage is optional */ }
